import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"🏗️ 系统总体架构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),d={name:"guide/architecture.md"};function l(o,t,i,p,r,c){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="🏗️-系统总体架构" tabindex="-1">🏗️ 系统总体架构 <a class="header-anchor" href="#🏗️-系统总体架构" aria-label="Permalink to &quot;🏗️ 系统总体架构&quot;">​</a></h1><p>MzMedia 采用清晰的层次化设计，覆盖感知层、边缘计算、协议接入、消息总线、业务中台到数字驾驶舱的完整端到端链路：</p><hr><h2 id="架构拓扑分层" tabindex="-1">架构拓扑分层 <a class="header-anchor" href="#架构拓扑分层" aria-label="Permalink to &quot;架构拓扑分层&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │                    应用层 (Application / Presentation)                  │</span></span>
<span class="line"><span> │  · 领导全景驾驶舱    · 工业物联网大屏   · 智慧园区/农业套件   · 移动端APP/H5  │</span></span>
<span class="line"><span> └───────────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                                     │</span></span>
<span class="line"><span> ┌───────────────────────────────────▼────────────────────────────────────┐</span></span>
<span class="line"><span> │                    业务中台层 (Business Service Layer)                  │</span></span>
<span class="line"><span> │  · yudao-module-media: GB28181 视频监控 / PTZ 云台 / ZLMediaKit 流媒体   │</span></span>
<span class="line"><span> │  · yudao-module-iot: 物联网设备全生命周期 / TSL 物模型 / 告警与 OTA      │</span></span>
<span class="line"><span> │  · yudao-module-ai1-springai: Spring AI 1.1+ / MCP Agent / 时序 RAG 诊断 │</span></span>
<span class="line"><span> │  · yudao-module-pms: 物联网工程交付看板 / 项目里程碑 / 敏捷任务 / 知识库 │</span></span>
<span class="line"><span> │  · yudao-module-mes: 车间工单排产 / 设备保养 / 告警联动维修 / Andon 安灯 │</span></span>
<span class="line"><span> │  · yudao-module-wms: 仓储库位建模 / 备品备件库存预占 / SN 扫码出入库   │</span></span>
<span class="line"><span> │  · yudao-module-report: GoView 拖拽大屏设计器 / 积木报表复杂套打       │</span></span>
<span class="line"><span> └───────────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                                     │</span></span>
<span class="line"><span> ┌───────────────────────────────────▼────────────────────────────────────┐</span></span>
<span class="line"><span> │                    接入与规则层 (Access &amp; Rule Engine)                  │</span></span>
<span class="line"><span> │  · 多协议网关: MQTT (EMQX) / Modbus TCP/RTU / CoAP / TCP / UDP / WS     │</span></span>
<span class="line"><span> │  · 数据分发引擎: SpEL 表达式过滤 -&gt; 9 种 Sink 输出 (TDengine / MQ / Webhook)│</span></span>
<span class="line"><span> │  · 场景联动引擎: TCA 架构 (Trigger-Condition-Action) 联动安防与工单     │</span></span>
<span class="line"><span> └───────────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                                     │</span></span>
<span class="line"><span> ┌───────────────────────────────────▼────────────────────────────────────┐</span></span>
<span class="line"><span> │                    存储与中间件层 (Storage &amp; Middleware)                │</span></span>
<span class="line"><span> │  · 关系型数据库: MySQL 8.0+ (业务实体, RBAC 权限, 多租户配置)          │</span></span>
<span class="line"><span> │  · 高性能时序库: TDengine 3.0+ (遥测数据超级表, 列式高压缩时序存储)    │</span></span>
<span class="line"><span> │  · 缓存与流式队列: Redis 7.x / Redisson (分布式锁, 会话, 内存总线)     │</span></span>
<span class="line"><span> │  · 分布式消息队列: Kafka / RocketMQ / RabbitMQ (可选高吞吐通道)        │</span></span>
<span class="line"><span> │  · 对象与文件存储: MinIO / 阿里云 OSS / 本地磁盘 (视频切片, 抓拍快照)   │</span></span>
<span class="line"><span> └────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="模块清单与职责全景" tabindex="-1">模块清单与职责全景 <a class="header-anchor" href="#模块清单与职责全景" aria-label="Permalink to &quot;模块清单与职责全景&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">模块名称</th><th style="text-align:left;">源码工程目录</th><th style="text-align:left;">核心定位与关键职责</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>yudao-dependencies</code></strong></td><td style="text-align:left;"><code>yudao-dependencies</code></td><td style="text-align:left;">全局依赖 BOM 统一锁定版本（Spring Boot 4.1.2、JDK 21、Netty、MapStruct、JAIN-SIP 等）。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-framework</code></strong></td><td style="text-align:left;"><code>yudao-framework</code></td><td style="text-align:left;">通用 Starter 基础设施：多租户自动 SQL 拦截、Redis 缓存与限流、全局异常拦截、WebSocket。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-media</code></strong></td><td style="text-align:left;"><code>yudao-module-media</code></td><td style="text-align:left;">国标 GB/T 28181（2016/2022）SIP 协议栈、ZLMediaKit 集群对接、WebRTC 低延迟播放、云台 PTZ 控制。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-iot</code></strong></td><td style="text-align:left;"><code>yudao-module-iot</code></td><td style="text-align:left;">13+ 种协议网关、TSL 物模型、Modbus 点位轮询调度、双核心规则引擎与 TDengine 存储驱动。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-ai1-springai</code></strong></td><td style="text-align:left;"><code>yudao-module-ai1-springai</code></td><td style="text-align:left;">Spring AI 1.1+ 框架集成、官方 Java MCP 客户端管理、时序数据 RAG 诊断排查、私有协议逆向解析。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-pms</code></strong></td><td style="text-align:left;"><code>yudao-module-pms</code></td><td style="text-align:left;">物联网工程交付管理：勘测、安装、通电、入网、验收节点看板、工作项协同与工程图纸知识库。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-mes</code></strong></td><td style="text-align:left;"><code>yudao-module-mes</code></td><td style="text-align:left;">智能制造执行：生产日历排程、工位 SOP 指导、设备资产台账、IoT 报警联动维修单、Andon 安灯呼叫。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-wms</code></strong></td><td style="text-align:left;"><code>yudao-module-wms</code></td><td style="text-align:left;">智能仓储管理：多仓库/库区/库位三级结构、备品备件库存预占、传感器单品条码追踪、先进先出 FIFO。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-report</code></strong></td><td style="text-align:left;"><code>yudao-module-report</code></td><td style="text-align:left;">开箱集成 GoView 拖拽式大屏设计器与积木报表（JimuReport），支持嵌入 WebRTC 视频与 TDengine 曲线。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-system</code></strong></td><td style="text-align:left;"><code>yudao-module-system</code></td><td style="text-align:left;">基础权限与系统底座：SaaS 多租户数据强隔离、RBAC 细粒度权限控制、OAuth2.0 与统一认证。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-module-infra</code></strong></td><td style="text-align:left;"><code>yudao-module-infra</code></td><td style="text-align:left;">基础设施支持：低代码生成器（Codegen）、分布式任务调度（Quartz/XXL）、文件对象存储。</td></tr><tr><td style="text-align:left;"><strong><code>yudao-server</code></strong></td><td style="text-align:left;"><code>yudao-server</code></td><td style="text-align:left;">Spring Boot 主启动入口，包含全量配置及启动类 <code>YudaoServerApplication</code>。</td></tr><tr><td style="text-align:left;"><strong><code>ui</code></strong></td><td style="text-align:left;"><code>ui</code></td><td style="text-align:left;">专有 Vue 3.4 + TypeScript + Vite 5 前端工程，集成 Jessibuca 视频播放器与物模型可视化设计器。</td></tr></tbody></table><hr><h2 id="跨模块解耦机制" tabindex="-1">跨模块解耦机制 <a class="header-anchor" href="#跨模块解耦机制" aria-label="Permalink to &quot;跨模块解耦机制&quot;">​</a></h2><p>MzMedia 严禁模块间的强代码硬编码引用。系统通过两大机制实现解耦：</p><ol><li><strong>Spring ApplicationEvent 进程内解耦</strong>：例如 <code>yudao-module-iot</code> 触发场景规则后，发布 <code>IotMediaLinkageEvent</code> 事件，由 <code>yudao-module-media</code> 中的监听器消费，完成摄像头预置位转动。</li><li><strong>IotMessageBus 跨服务解耦</strong>：基于 Redis Stream（默认）或 Kafka/RocketMQ 传输遥测报文与命令。</li></ol>`,12)])])}const y=e(d,[["render",l]]);export{u as __pageData,y as default};
